SELECT event_date, brand_id, impressions, clicks, ctr
FROM agg_brand_daily
WHERE event_date = DATE '2017-05-12' AND brand_id = 400399;

SELECT event_date, brand_id, unique_users, unique_clickers
FROM reach_brand_daily
WHERE event_date = DATE '2017-05-12' AND brand_id = 400399;

SELECT event_date, brand_id, unique_users, unique_clickers
FROM reach_brand_daily
WHERE event_date = DATE '2017-05-11' AND brand_id = 400399;

SELECT campaign_id, clicks
FROM live_campaign_last6h
WHERE campaign_id = 154203;

SELECT campaign_id, unique_clickers
FROM live_reach_campaign_last6h
WHERE campaign_id = 154203;

SELECT campaign_id, advertiser_id
FROM live_campaign_last6h
WHERE campaign_id = 154203;
